package com.vibeguard.samples.inventory; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import java.util.concurrent.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/inventory/{sku}/adjustments") public class AdjustmentController {private final Map<String,List<Adjustment>> history=new ConcurrentHashMap<>();@PostMapping public ResponseEntity<Adjustment> adjust(@PathVariable String sku,@Valid @RequestBody Request request){Adjustment adjustment=new Adjustment(request.delta(),request.reason(),Instant.now());history.computeIfAbsent(sku,x->new ArrayList<>()).add(adjustment);return ResponseEntity.status(201).body(adjustment);}@GetMapping public List<Adjustment> list(@PathVariable String sku){return List.copyOf(history.getOrDefault(sku,List.of()));}record Request(int delta,@NotBlank String reason){}record Adjustment(int delta,String reason,Instant createdAt){} }
